function parseBranchNotation(branch) {
	const branchVersions = [0, 0];
	const versions = branch.split("-");
	if (versions.length !== 2) throw new Error(`The branch must have 2 versions separated by dash. branch: ${branch}`);
	for (let i = 0; i < versions.length; i++) {
		let version = versions[i];
		let includeFutureVersions = false;
		if (i == versions.length - 1 && version.endsWith("+")) {
			includeFutureVersions = true;
			version.substring(0, version.length - 1);
		}
		if (version.startsWith("2.1.")) {
			const versionNumber = parseInt(version.substring(4), 10);
			if (Number.isNaN(versionNumber)) throw new Error(`Invalid version in branch. branch ${branch}`);
			branchVersions[i] = versionNumber;
		} else {
			const versionNumberStrings = version.split(".");
			if (versionNumberStrings.length > 3) throw new Error(`Invalid version in branch. branch ${branch}`);
			let multiplier = 1e4;
			for (const versionNumberString of versionNumberStrings) {
				const versionNumber = parseInt(versionNumberString, 10);
				if (Number.isNaN(versionNumber) || versionNumber >= 100) throw new Error(`Invalid version in branch. branch ${branch}`);
				branchVersions[i] += versionNumber * multiplier;
				multiplier /= 100;
			}
		}
		if (i == versions.length - 1 && !includeFutureVersions) branchVersions[i] = -branchVersions[i];
	}
	return {
		minVersion: branchVersions[0],
		maxVersion: branchVersions[1]
	};
}
